changeSet.sql:
CREATE OR REPLACE FUNCTION public.sync_customer_profile() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
 IF NEW.role = 'customer' THEN
  INSERT INTO public.customers(id,profile_id,full_name,email,phone,address,created_at,updated_at)
   VALUES(NEW.id,NEW.id,COALESCE(NEW.full_name,''),NEW.email,NEW.phone,NEW.default_address,NEW.created_at,NEW.updated_at)
   ON CONFLICT(profile_id) DO UPDATE SET full_name=EXCLUDED.full_name,email=EXCLUDED.email,phone=EXCLUDED.phone,address=EXCLUDED.address,updated_at=EXCLUDED.updated_at;
 ELSE
  DELETE FROM public.customers WHERE profile_id = NEW.id;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.sync_customer_profile() FROM PUBLIC;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON FUNCTION public.sync_customer_profile() FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON FUNCTION public.sync_customer_profile() FROM authenticated;
  END IF;
END $$;
